package com.centralplay.app.ui;
import android.content.Context;import android.net.*;import android.os.Bundle;import android.widget.TextView;import androidx.appcompat.app.AppCompatActivity;import com.centralplay.app.R;import com.centralplay.app.data.Prefs;import com.google.android.material.appbar.MaterialToolbar;import java.net.*;import java.util.concurrent.Executors;import okhttp3.*;
public class DiagnosticsActivity extends AppCompatActivity{private TextView out;@Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_diagnostics);MaterialToolbar tb=findViewById(R.id.toolbar);tb.setNavigationOnClickListener(v->finish());out=findViewById(R.id.results);findViewById(R.id.run).setOnClickListener(v->run());run();}private void run(){out.setText("Ejecutando…");Executors.newSingleThreadExecutor().execute(()->{StringBuilder s=new StringBuilder();try{ConnectivityManager cm=(ConnectivityManager)getSystemService(Context.CONNECTIVITY_SERVICE);Network n=cm.getActiveNetwork();NetworkCapabilities cap=cm.getNetworkCapabilities(n);s.append("Red activa: ").append(n!=null).append('\n');s.append("Internet validada: ").append(cap!=null&&cap.hasCapability(NetworkCapabilities.NET_CAPABILITY_VALIDATED)).append('\n');}catch(Exception e){s.append("Red: ERROR ").append(e.getMessage()).append('\n');}String url=Prefs.manifestUrl(this);s.append("Manifest: ").append(url.trim().isEmpty()?"<demo local>":url).append('\n');if(!url.trim().isEmpty()){try{URI u=new URI(url);String host=u.getHost();long t=System.currentTimeMillis();InetAddress a=InetAddress.getByName(host);s.append("DNS: ").append(a.getHostAddress()).append(" (").append(System.currentTimeMillis()-t).append(" ms)\n");}catch(Exception e){s.append("DNS: ERROR ").append(e.getMessage()).append('\n');}try(Response r=new OkHttpClient().newCall(new Request.Builder().url(url).header("User-Agent","CentralPlay/1.0").build()).execute()){s.append("HTTP: ").append(r.code()).append(' ').append(r.message()).append('\n');}catch(Exception e){s.append("HTTP: ERROR ").append(e.getMessage()).append('\n');}}runOnUiThread(()->out.setText(s.toString()));});}}
